import{_ as e,o,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Custom-Currency-Formats.md","filePath":"manual-en/Custom-Currency-Formats.md","lastUpdated":1785684581000}'),s={name:"manual-en/Custom-Currency-Formats.md"};function u(n,t,d,m,i,c){return o(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_6-7-4-2-custom-currency-formats" tabindex="-1">6.7.4.2 Custom Currency Formats <a class="header-anchor" href="#_6-7-4-2-custom-currency-formats" aria-label="Permalink to &quot;6.7.4.2 Custom Currency Formats&quot;">​</a></h4><p>The custom currency formats are closely related to the basic numeric formats, but they allow users to customize the output format. The SET command configures custom currency formats, using the syntax</p><pre><code>SET CCx=&quot;string&quot;.
</code></pre><p>where x is A, B, C, D, or E, and string is no more than 16 characters long.</p><p>string must contain exactly three commas or exactly three periods (but not both), except that a single quote character may be used to “escape” a following comma, period, or single quote. If three commas are used, commas are used for grouping in output, and a period is used as the decimal point. Uses of periods reverses these roles.</p><p>The commas or periods divide string into four fields, called the <em>negative prefix</em> , <em>prefix</em> , <em>suffix</em> , and <em>negative suffix</em> , respectively. The prefix and suffix are added to output whenever space is available. The negative prefix and negative suffix are always added to a negative number when the output includes a nonzero digit.</p><p>The following syntax shows how custom currency formats could be used to reproduce basic numeric formats:</p><pre><code>SET CCA=&quot;-,,,&quot;.  /* Same as COMMA.
SET CCB=&quot;-...&quot;.  /* Same as DOT.
SET CCC=&quot;-,$,,&quot;. /* Same as DOLLAR.
SET CCD=&quot;-,,%,&quot;. /* Like PCT, but groups with commas.
</code></pre><p>Here are some more examples of custom currency formats. The final example shows how to use a single quote to escape a delimiter:</p><pre><code>SET CCA=&quot;,EUR,,-&quot;.   /* Euro.
SET CCB=&quot;(,USD ,,)&quot;. /* US dollar.
SET CCC=&quot;-.R$..&quot;.    /* Brazilian real.
SET CCD=&quot;-,, NIS,&quot;.  /* Israel shekel.
SET CCE=&quot;-.Rp&#39;. ..&quot;. /* Indonesia Rupiah.
</code></pre><p>These formats would yield the following output:</p><table tabindex="0"><thead><tr><th>Format</th><th>3145.59</th><th>-3145.59</th></tr></thead><tbody><tr><td>CCA12.2</td><td>EUR3,145.59</td><td>EUR3,145.59-</td></tr><tr><td>CCB14.2</td><td>USD 3,145.59</td><td>(USD 3,145.59)</td></tr><tr><td>CCC11.2</td><td>R$3.145,59</td><td>-R$3.145,59</td></tr><tr><td>CCD13.2</td><td>3,145.59 NIS</td><td>-3,145.59 NIS</td></tr><tr><td>CCE10.0</td><td>Rp. 3.146</td><td>-Rp. 3.146</td></tr></tbody></table><p>The default for all the custom currency formats is ‘-,,,’, equivalent to COMMA format.</p>`,13)])])}const h=e(s,[["render",u]]);export{p as __pageData,h as default};
